// Version manager UI: renders versions.json (generated by tools/build-versions.py)
(function () {
  var $ = function (id) { return document.getElementById(id); };
  var esc = function (s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };
  var st = { q: '', sort: 'new', proj: 'all' }; var D;
  try { var u = new URLSearchParams(location.search); st.q = u.get('q') || ''; st.proj = u.get('p') || 'all'; st.sort = u.get('sort') === 'old' ? 'old' : 'new'; } catch (e) {}
  function card(p, v) {
    var bd = v.badges.filter(function (b) { return b !== v.label; }).map(function (b) { return '<span class="bdg ' + (b === 'latest' ? 'latest' : 'rel') + '">' + esc(b === 'latest' ? 'LATEST' : b) + '</span>'; }).join('');
    var hay = [p.name, v.label, v.name, v.title, v.desc, v.commit, v.repo, v.date_vie].join(' ').toLowerCase();
    return '<article class="card" data-q="' + esc(hay) + '" data-date="' + esc(v.date) + '" id="' + esc(p.id + '-' + v.slug) + '" style="--c:' + esc(p.color) + '">' +
      '<a class="thumb" href="' + esc(v.path) + '" aria-label="Play ' + esc(v.name) + '">' + (v.thumb ? '<img src="' + esc(v.thumb) + '" alt="" loading="lazy" width="480" height="222">' : '') +
      '<span class="lbl">' + esc(v.label.toUpperCase()) + '</span><span class="badges">' + bd + '</span><span class="play">▶</span></a>' +
      '<div class="body"><h3 class="ink">' + esc(v.title.toUpperCase()) + '</h3><p>' + esc(v.desc) + '</p>' +
      '<div class="meta"><span>' + esc(v.date_vie) + ' Vienna</span><a class="h" href="' + esc(v.url_commit) + '" target="_blank" rel="noopener">' + esc(v.commit) + '</a><span>' + esc(v.repo.split('/')[1]) + '</span>' +
      (v.smoke && v.smoke.ok ? '<span class="ok" title="headless smoke test passed">✓ tested</span>' : '') + '</div>' +
      '<div class="cta"><a class="btn y" href="' + esc(v.path) + '">▶ PLAY ' + esc(v.label.toUpperCase()) + '</a>' + (v.release ? '<a class="btn sm" href="' + esc(v.release) + '" target="_blank" rel="noopener">RELEASE</a>' : '') + '</div></div></article>';
  }
  function logItem(c) {
    var hay = [c.msg, c.body, c.commit, c.repo, c.version || '', c.date_vie].join(' ').toLowerCase();
    return '<li data-q="' + esc(hay) + '"><span class="d">' + esc(c.date_vie) + '</span> <a class="h" href="' + esc(c.url) + '" target="_blank" rel="noopener">' + esc(c.commit) + '</a> <span class="r">' + esc(c.repo.split('/')[1]) + '</span>' +
      (c.version ? '<span class="v">' + esc(c.version.toUpperCase()) + '</span>' : '') + '<span class="m">' + esc(c.msg) + '</span></li>';
  }
  function render() {
    var L = $('list'); L.innerHTML = '';
    D.projects.forEach(function (p) {
      var vs = p.versions.slice().sort(function (a, b) { return st.sort === 'old' ? a.date.localeCompare(b.date) : b.date.localeCompare(a.date); });
      var log = p.changelog.slice().sort(function (a, b) { return st.sort === 'old' ? a.date.localeCompare(b.date) : b.date.localeCompare(a.date); });
      var s = document.createElement('section'); s.className = 'proj'; s.id = 'p-' + p.id; s.dataset.id = p.id; s.style.setProperty('--c', p.color);
      s.innerHTML = '<div class="ph"><h2 class="ink">' + esc(p.name.toUpperCase()) + '</h2><p>' + esc(p.tagline) + '</p><div class="links">' +
        (p.live ? '<a class="btn" href="' + esc(p.live) + '">LIVE (LATEST CODE)</a>' : '') + p.repos.map(function (r) { return '<a class="btn" href="https://github.com/' + esc(r) + '" target="_blank" rel="noopener">' + esc(r.split('/')[1]) + ' ↗</a>'; }).join('') + '</div></div>' +
        '<div class="grid">' + vs.map(function (v) { return card(p, v); }).join('') + '</div>' +
        '<details class="log"><summary>CHANGELOG · ALL ' + log.length + ' COMMITS</summary><ol>' + log.map(logItem).join('') + '</ol></details>';
      L.appendChild(s);
    });
    filter();
  }
  function filter() {
    var q = st.q.trim().toLowerCase(), any = false;
    document.querySelectorAll('section.proj').forEach(function (s) {
      var on = st.proj === 'all' || st.proj === s.dataset.id, n = 0, nl = 0;
      s.querySelectorAll('.card').forEach(function (c) { var m = on && (!q || c.dataset.q.indexOf(q) >= 0); c.classList.toggle('hide', !m); if (m) n++; });
      s.querySelectorAll('.log li').forEach(function (c) { var m = !q || c.dataset.q.indexOf(q) >= 0; c.classList.toggle('hide', !m); if (m) nl++; });
      var d = s.querySelector('details.log'); if (q && nl && !n) d.open = true;
      s.style.display = on && (n || (q && nl)) ? '' : 'none'; if (on && (n || (q && nl))) any = true;
    });
    $('empty').style.display = any ? 'none' : 'block';
    document.querySelectorAll('.chip').forEach(function (c) { c.classList.toggle('on', c.dataset.id === st.proj); });
    try { var u = new URLSearchParams(); if (st.q) u.set('q', st.q); if (st.proj !== 'all') u.set('p', st.proj); if (st.sort !== 'new') u.set('sort', st.sort); history.replaceState(null, '', u.toString() ? '?' + u : location.pathname); } catch (e) {}
  }
  function hero() {
    var p = D.projects[0], v = p.versions.filter(function (x) { return x.badges.indexOf('V0.1') >= 0; })[0] || p.versions[p.versions.length - 1];
    var n = D.projects.reduce(function (a, p) { return a + p.versions.length; }, 0);
    $('hero').innerHTML = '<div class="t"><h2 class="ink">' + esc(v.name.toUpperCase()) + ' IS OUT</h2><p>' + n + ' playable frozen builds across ' + D.projects.length + ' projects. Pick any version and drive it exactly as it was.</p></div>' +
      '<a class="btn o" href="' + esc(v.path) + '">▶ PLAY ' + esc(v.label) + '</a>' + (v.release ? '<a class="btn" href="' + esc(v.release) + '" target="_blank" rel="noopener">RELEASE NOTES</a>' : '');
  }
  fetch('versions.json', { cache: 'no-cache' }).then(function (r) { return r.json(); }).then(function (d) {
    D = d; hero();
    var ch = $('chips'); ch.innerHTML = '<button class="chip" data-id="all">ALL</button>' + d.projects.map(function (p) { return '<button class="chip" data-id="' + esc(p.id) + '" style="--c:' + esc(p.color) + '">' + esc(p.name.toUpperCase()) + ' · ' + p.versions.length + '</button>'; }).join('');
    ch.onclick = function (e) { var b = e.target.closest('.chip'); if (b) { st.proj = b.dataset.id; filter(); } };
    $('q').value = st.q; $('q').oninput = function () { st.q = this.value; filter(); };
    $('sort').value = st.sort; $('sort').onchange = function () { st.sort = this.value; render(); };
    $('gen').textContent = 'Updated ' + d.generated.replace('T', ' ').slice(0, 16) + ' Vienna.';
    render();
  }).catch(function (e) { $('list').innerHTML = '<p>Could not load versions.json: ' + esc(e.message) + '</p>'; });
})();
